INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-01','grammar_mcq','P5',2,'{"prompt": "Choose the sentence with correct subject-verb agreement.", "options": ["The basket of apples is on the table.", "The basket of apples are on the table.", "The basket of apples were on the table.", "The basket of apples have on the table."]}','{"answer": "The basket of apples is on the table."}','{"explanation": "The subject is \\u201cbasket\\u201d, which is singular."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-01','R-GRAMMAR',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-02','vocabulary_mcq','P5',2,'{"prompt": "Maya was reluctant to speak in front of the class. What does \\u201creluctant\\u201d mean?", "options": ["unwilling", "excited", "careless", "noisy"]}','{"answer": "unwilling"}','{"explanation": "Reluctant means unwilling or hesitant."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-02','R-VOCAB',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-03','vocabulary_cloze','P5',2,'{"prompt": "The hikers were tired, but they ____ walking until they reached the shelter.", "options": ["continued", "escaped", "borrowed", "whispered"]}','{"answer": "continued"}','{"explanation": "\\u201cContinued\\u201d fits the meaning of carrying on with an action."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-03','R-VOCABCLOZE',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-04','grammar_cloze','P5',2,'{"prompt": "Neither Ben nor his friends ____ ready to leave.", "options": ["is", "are", "was", "has"]}','{"answer": "are"}','{"explanation": "With neither\\u2026nor, the verb agrees with the nearer subject \\u201cfriends\\u201d."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-04','R-GRAMMARCLOZE',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-05','editing_spelling','P5',2,'{"prompt": "Identify and correct the misspelt word: The scientist carefully observed the unusual behavour of the ants."}','{"acceptedAnswers": ["behaviour"], "answer": "behaviour"}','{"explanation": "The correct British English spelling is \\u201cbehaviour\\u201d."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-05','R-EDIT-SPELL',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-06','editing_grammar','P5',2,'{"prompt": "Correct the grammar error: She has went to the library twice this week."}','{"acceptedAnswers": ["She has gone to the library twice this week."], "answer": "She has gone to the library twice this week."}','{"explanation": "The present perfect uses has/have + past participle: has gone."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-06','R-EDIT-GRAM',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-07','synthesis','P6',3,'{"prompt": "Rewrite using \\u201cdespite\\u201d: The rain was heavy. The match continued."}','{"acceptedAnswers": ["Despite the heavy rain, the match continued."], "answer": "Despite the heavy rain, the match continued."}','{"explanation": "\\u201cDespite\\u201d is followed by a noun phrase or gerund."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
INSERT OR IGNORE INTO question_skills (question_id,skill_id,weight) VALUES ('q-v05-07','R-SYNTH',1);
INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-08','open_comprehension','P6',3,'{"prompt": "Nina checked the map twice before leaving the trail. What does this suggest about her?"}','{"acceptedAnswers": ["She was careful and wanted to avoid getting lost."], "answer": "She was careful and wanted to avoid getting lost."}','{"explanation": "Her repeated checking suggests caution and concern about direction."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
