INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-09','grammar_mcq','P6',3,'{"prompt": "If I ____ earlier, I would have caught the bus.", "options": ["had left", "left", "have left", "would leave"]}','{"answer": "had left"}','{"explanation": "A third conditional uses if + past perfect."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
