INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-10','vocabulary_mcq','P6',3,'{"prompt": "The coach praised Amir for his perseverance. What does \\u201cperseverance\\u201d mean?", "options": ["continued effort despite difficulty", "natural talent", "quick movement", "strict discipline"]}','{"answer": "continued effort despite difficulty"}','{"explanation": "Perseverance means continuing despite difficulty."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
