INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-11','comprehension_cloze','P6',3,'{"prompt": "The old bridge was closed because engineers found that several supports were ____.", "options": ["damaged", "cheerful", "patient", "ordinary"]}','{"answer": "damaged"}','{"explanation": "\\u201cDamaged\\u201d logically explains why the bridge was unsafe."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
