INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-12','visual_text','P6',3,'{"prompt": "A poster says: \\u201cBring your own bottle. Refill stations are available at every level.\\u201d What is the main purpose?", "options": ["To encourage reusable bottles", "To sell bottled water", "To warn people about spills", "To advertise a new caf\\u00e9"]}','{"answer": "To encourage reusable bottles"}','{"explanation": "The wording encourages a reusable habit."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
