INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-13','synthesis','P6',3,'{"prompt": "Combine using \\u201cunless\\u201d: You revise your work. You may miss several mistakes."}','{"acceptedAnswers": ["Unless you revise your work, you may miss several mistakes."], "answer": "Unless you revise your work, you may miss several mistakes."}','{"explanation": "\\u201cUnless\\u201d means \\u201cif not\\u201d."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
