INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,curriculum_version_id,generation_model,marks) VALUES ('q-v05-18','open_comprehension','P6',4,'{"prompt": "Why does an author include a short personal anecdote before presenting facts about recycling?"}','{"acceptedAnswers": ["To engage readers and connect the topic to a relatable experience."], "answer": "To engage readers and connect the topic to a relatable experience."}','{"explanation": "An anecdote can establish relevance and interest before factual explanation."}','published','SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5',1);
